-- Rebuild Medina Book 4 lesson 13 strictly from the supplied Arabic sharh.
-- Canonical PDF pages: 53-56. DOC text was used only for extraction and checked against the PDF.
begin;

do $migration$
declare
  existing_count integer;
begin
  select count(*) into existing_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '13';
  if existing_count = 2 then
    update public.rules
    set sort_order = 5
    where course_name = 'Мединский курс (Том 4)'
      and lesson_number = '13'
      and sort_order = 2;

    insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar)
    values
      ('Мединский курс (Том 4)', '13', '__book4_lesson13_dhat__', '', 2, 'rule', '', null),
      ('Мединский курс (Том 4)', '13', '__book4_lesson13_mulhaq__', '', 3, 'rule', '', null),
      ('Мединский курс (Том 4)', '13', '__book4_lesson13_nisba__', '', 4, 'rule', '', null);
  elsif existing_count <> 5 then
    raise exception 'Expected 2 legacy or 5 rebuilt Book 4 lesson 13 rules, found %', existing_count;
  end if;
end $migration$;

with incoming(sort_order, title, content, summary, rule_ar) as (
  values
    (1, 'التَّمْيِيزُ وَنَوْعَاهُ (разъясняющее имя и два его вида)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-object" dir="rtl" lang="ar">التَّمْيِيزُ اسْمٌ نَكِرَةٌ يَتَضَمَّنُ مَعْنَى «مِنْ» الْبَيَانِيَّةِ، وَيُذْكَرُ لِبَيَانِ مَا قَبْلَهُ مِنْ إِبْهَامٍ أَوْ إِجْمَالٍ. وَهُوَ نَوْعَانِ: تَمْيِيزُ الذَّاتِ وَتَمْيِيزُ النِّسْبَةِ.</span><p class="rule-study-text">تَمْيِيزٌ — неопределённое имя со значением пояснительного مِنْ, устраняющее неясность или обобщённость предыдущего выражения. Он бывает разъяснением отдельной меры или предмета и разъяснением отношения внутри предложения.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Определение</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-object"><span class="rule-term-ar ar-tone-object" dir="rtl" lang="ar">اسْمٌ نَكِرَةٌ</span><span class="rule-term-ru">неопределённое имя</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar ar-tone-particle" dir="rtl" lang="ar">«مِنْ» الْبَيَانِيَّةُ</span><span class="rule-term-ru">пояснительное значение «из / в отношении»</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar ar-tone-predicate" dir="rtl" lang="ar">إِزَالَةُ الْإِبْهَامِ أَوِ الْإِجْمَالِ</span><span class="rule-term-ru">устранение неясности или обобщённости</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Два вида</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مَا يُوَضِّحُهُ</span><span class="rule-table-ru">что разъясняет</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русское пояснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">تَمْيِيزُ الذَّاتِ</span><span class="rule-table-ru">разъяснение предмета или меры</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كَلِمَةٌ مُبْهَمَةٌ</span><span class="rule-table-ru">неясное отдельное слово</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يَأْتِي بَعْدَ مِقْدَارٍ أَوْ مَا يُشْبِهُهُ</span><span class="rule-table-ru">следует после меры либо сходного с мерой выражения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">تَمْيِيزُ النِّسْبَةِ</span><span class="rule-table-ru">разъяснение отношения</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جُمْلَةٌ مُبْهَمَةُ النِّسْبَةِ</span><span class="rule-table-ru">предложение с неясным отношением</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يُبَيِّنُ جِهَةَ النِّسْبَةِ فِي الْجُمْلَةِ</span><span class="rule-table-ru">показывает, в каком отношении верно всё предложение</span></td></tr></tbody></table></div></div></div>', 'تَمْيِيزٌ — неопределённое имя со значением пояснительного مِنْ, устраняющее неясность или обобщённость предыдущего выражения. Он бывает разъяснением отдельной меры или предмета и разъяснением отношения внутри предложения.', 'التَّمْيِيزُ اسْمٌ نَكِرَةٌ يَتَضَمَّنُ مَعْنَى «مِنْ» الْبَيَانِيَّةِ، وَيُذْكَرُ لِبَيَانِ مَا قَبْلَهُ مِنْ إِبْهَامٍ أَوْ إِجْمَالٍ. وَهُوَ نَوْعَانِ: تَمْيِيزُ الذَّاتِ وَتَمْيِيزُ النِّسْبَةِ.'),
    (2, 'تَمْيِيزُ الذَّاتِ (разъяснение предмета или меры)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-object" dir="rtl" lang="ar">تَمْيِيزُ الذَّاتِ يُوَضِّحُ كَلِمَةً مُبْهَمَةً قَبْلَهُ، وَيَقَعُ بَعْدَ الْمَقَادِيرِ الْأَرْبَعَةِ: الْمَقَايِيسِ، وَالْمَوْزُونَاتِ، وَالْمَكِيلَاتِ، وَالْعَدَدِ. وَيَجُوزُ فِيهِ النَّصْبُ، وَالْجَرُّ بِحَرْفِ «مِنْ» الْبَيَانِيِّ، وَالْجَرُّ بِالْإِضَافَةِ.</span><p class="rule-study-text">تَمْيِيزُ الذَّاتِ разъясняет предшествующее неясное слово и употребляется после меры площади или длины, веса, объёма и числа. Допустимы винительный падеж, родительный с пояснительным مِنْ и родительный через идафу.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Четыре вида мер</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَوْعُ الْمِقْدَارِ</span><span class="rule-table-ru">вид меры</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَقَايِيسُ أَوِ الْمَمْسُوحَاتُ</span><span class="rule-table-ru">меры длины или площади</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">عِنْدِي مِتْرٌ قُمَاشًا؛ بِعْتُ ذِرَاعًا وَرَقًا.</span><span class="rule-table-ru">У меня метр ткани; я продал локоть бумаги.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَسَاحَةُ</span><span class="rule-table-ru">измерение пространства</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَوْزُونَاتُ</span><span class="rule-table-ru">меры веса</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">تَصَدَّقْتُ بِغِرَامٍ ذَهَبًا؛ اِشْتَرَيْتُ رِطْلًا عَسَلًا.</span><span class="rule-table-ru">Я пожертвовал грамм золота; купил ратль мёда.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْوَزْنُ</span><span class="rule-table-ru">взвешиваемое количество</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَكِيلَاتُ</span><span class="rule-table-ru">меры объёма</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">دَفَعْتُ صَاعًا تَمْرًا؛ لَهُ قَفِيزٌ بُرًّا.</span><span class="rule-table-ru">Я передал са‘ фиников; у него кафиз пшеницы.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْقَفِيزُ مِكْيَالٌ قَدِيمٌ</span><span class="rule-table-ru">кафиз — старинная мера объёма</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعَدَدُ وَكِنَايَةُ الْعَدَدِ</span><span class="rule-table-ru">число и вопрос о числе</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">قَرَأْتُ أَحَدَ عَشَرَ كِتَابًا؛ كَمْ كِتَابًا عِنْدَكَ؟</span><span class="rule-table-ru">Я прочитал одиннадцать книг; сколько у тебя книг?</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مَا بَعْدَ الْعَدَدِ</span><span class="rule-table-ru">слово после числа снимает его неопределённость</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Три допустимых оформления</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْوَجْهُ الْإِعْرَابِيُّ</span><span class="rule-table-ru">вариант</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْإِعْرَابُ</span><span class="rule-table-ru">разбор</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">النَّصْبُ</span><span class="rule-table-ru">винительный падеж</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">عِنْدِي مِتْرٌ قُمَاشًا.</span><span class="rule-table-ru">У меня метр ткани.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">قُمَاشًا: تَمْيِيزٌ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">قُمَاشًا — تَمْيِيزٌ в винительном падеже; показатель — фатха.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْجَرُّ بِحَرْفِ «مِنْ» الْبَيَانِيِّ</span><span class="rule-table-ru">родительный с مِنْ</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">عِنْدِي مِتْرٌ مِنْ قُمَاشٍ.</span><span class="rule-table-ru">У меня метр ткани.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">قُمَاشٍ: تَمْيِيزٌ مَجْرُورٌ بِمِنْ، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">قُمَاشٍ — تَمْيِيزٌ в родительном падеже после مِنْ; показатель — касра.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجَرُّ بِالْإِضَافَةِ</span><span class="rule-table-ru">родительный через идафу</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">عِنْدِي مِتْرُ قُمَاشٍ.</span><span class="rule-table-ru">У меня метр ткани.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">قُمَاشٍ: تَمْيِيزٌ مَجْرُورٌ بِالْإِضَافَةِ، وَعَلَامَةُ جَرِّهِ الْكَسْرَةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">قُمَاشٍ — تَمْيِيزٌ в родительном падеже через идафу; показатель — касра.</span></td></tr></tbody></table></div></div></div>', 'تَمْيِيزُ الذَّاتِ разъясняет предшествующее неясное слово и употребляется после меры площади или длины, веса, объёма и числа. Допустимы винительный падеж, родительный с пояснительным مِنْ и родительный через идафу.', 'تَمْيِيزُ الذَّاتِ يُوَضِّحُ كَلِمَةً مُبْهَمَةً قَبْلَهُ، وَيَقَعُ بَعْدَ الْمَقَادِيرِ الْأَرْبَعَةِ: الْمَقَايِيسِ، وَالْمَوْزُونَاتِ، وَالْمَكِيلَاتِ، وَالْعَدَدِ. وَيَجُوزُ فِيهِ النَّصْبُ، وَالْجَرُّ بِحَرْفِ «مِنْ» الْبَيَانِيِّ، وَالْجَرُّ بِالْإِضَافَةِ.'),
    (3, 'مَا يُلْحَقُ بِتَمْيِيزِ الذَّاتِ (выражения, приравненные к разъяснению меры)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-object" dir="rtl" lang="ar">يُلْحَقُ بِتَمْيِيزِ الذَّاتِ مَا يَدُلُّ عَلَى مَا يُشْبِهُ الْمِقْدَارَ مِنْ غَيْرِ أَنْ يَدُلَّ عَلَى مِقْدَارٍ مُعَيَّنٍ مَحْدُودٍ. وَتَجُوزُ فِيهِ الْأَوْجُهُ الثَّلَاثَةُ، فَإِنْ أُضِيفَ مَا يُشْبِهُ الْمِقْدَارَ إِلَى غَيْرِ التَّمْيِيزِ، جَازَ النَّصْبُ وَالْجَرُّ بِحَرْفِ «مِنْ» الْبَيَانِيِّ فَقَطْ، وَلَمْ يَجُزِ الْجَرُّ بِالْإِضَافَةِ.</span><p class="rule-study-text">К تَمْيِيزُ الذَّاتِ приравниваются слова, похожие на меру, но не задающие точного количества. Обычно доступны три оформления; если такое слово уже входит в другую идафу, остаются только винительный падеж и родительный с مِنْ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Сходство с мерой</span><div class="rule-example-list"><div class="rule-example-card rule-term-object"><span class="rule-example-ar ar-tone-object" dir="rtl" lang="ar">عِنْدِي كِيسٌ أَرُزًّا.</span><span class="rule-example-ru">У меня мешок риса: мешок похож на меру объёма.</span></div><div class="rule-example-card rule-term-object"><span class="rule-example-ar ar-tone-object" dir="rtl" lang="ar">اِشْتَرَيْتُ جَرَّةً عَسَلًا.</span><span class="rule-example-ru">Я купил кувшин мёда.</span></div><div class="rule-example-card rule-term-object"><span class="rule-example-ar ar-tone-object" dir="rtl" lang="ar">مَا فِي السَّمَاءِ قَدْرُ رَاحَةٍ سَحَابًا.</span><span class="rule-example-ru">На небе нет облака величиной с ладонь.</span></div><div class="rule-example-card rule-term-object"><span class="rule-example-ar ar-tone-object" dir="rtl" lang="ar">أُرِيدُ مِلْءَ مِلْعَقَةٍ عَسَلًا.</span><span class="rule-example-ru">Я хочу ложку, наполненную мёдом.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Три формы при свободном слове меры</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْوَجْهُ</span><span class="rule-table-ru">вариант</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">النَّصْبُ</span><span class="rule-table-ru">винительный</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">عِنْدِي كِيسٌ أَرُزًّا.</span><span class="rule-table-ru">У меня мешок риса.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">تَمْيِيزٌ مَنْصُوبٌ</span><span class="rule-table-ru">разъясняющее слово в винительном падеже</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْجَرُّ بِمِنْ</span><span class="rule-table-ru">родительный с مِنْ</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">عِنْدِي كِيسٌ مِنْ أَرُزٍّ.</span><span class="rule-table-ru">У меня мешок риса.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">تَمْيِيزٌ مَجْرُورٌ بِمِنْ</span><span class="rule-table-ru">разъясняющее слово после مِنْ</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجَرُّ بِالْإِضَافَةِ</span><span class="rule-table-ru">родительный через идафу</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">عِنْدِي كِيسُ أَرُزٍّ.</span><span class="rule-table-ru">У меня мешок риса.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">تَمْيِيزٌ مَجْرُورٌ بِالْإِضَافَةِ</span><span class="rule-table-ru">разъясняющее слово во второй позиции идафы</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Если слово меры уже входит в идафу</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْحُكْمُ</span><span class="rule-table-ru">допустимость</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يَجُوزُ النَّصْبُ</span><span class="rule-table-ru">винительный разрешён</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَا فِي السَّمَاءِ قَدْرُ رَاحَةٍ سَحَابًا؛ أُرِيدُ مِلْءَ مِلْعَقَةٍ عَسَلًا.</span><span class="rule-table-ru">На небе нет облака величиной с ладонь; хочу ложку мёда.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">سَحَابًا وَعَسَلًا</span><span class="rule-table-ru">разъясняющие слова стоят в винительном падеже</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يَجُوزُ الْجَرُّ بِحَرْفِ «مِنْ»</span><span class="rule-table-ru">родительный с مِنْ разрешён</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَا فِي السَّمَاءِ قَدْرُ رَاحَةٍ مِنْ سَحَابٍ؛ أُرِيدُ مِلْءَ مِلْعَقَةٍ مِنْ عَسَلٍ.</span><span class="rule-table-ru">На небе нет облака величиной с ладонь; хочу ложку мёда.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لَا يَجُوزُ الْجَرُّ بِالْإِضَافَةِ</span><span class="rule-table-ru">третья идафа здесь невозможна</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-list"><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿فَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرٗا يَرَهُۥ﴾</span><span class="rule-example-ru">Кто совершит добро весом с пылинку, увидит его: خَيْرًا разъясняет выражение меры مِثْقَالَ ذَرَّةٍ.</span></div></div></div></div>', 'К تَمْيِيزُ الذَّاتِ приравниваются слова, похожие на меру, но не задающие точного количества. Обычно доступны три оформления; если такое слово уже входит в другую идафу, остаются только винительный падеж и родительный с مِنْ.', 'يُلْحَقُ بِتَمْيِيزِ الذَّاتِ مَا يَدُلُّ عَلَى مَا يُشْبِهُ الْمِقْدَارَ مِنْ غَيْرِ أَنْ يَدُلَّ عَلَى مِقْدَارٍ مُعَيَّنٍ مَحْدُودٍ. وَتَجُوزُ فِيهِ الْأَوْجُهُ الثَّلَاثَةُ، فَإِنْ أُضِيفَ مَا يُشْبِهُ الْمِقْدَارَ إِلَى غَيْرِ التَّمْيِيزِ، جَازَ النَّصْبُ وَالْجَرُّ بِحَرْفِ «مِنْ» الْبَيَانِيِّ فَقَطْ، وَلَمْ يَجُزِ الْجَرُّ بِالْإِضَافَةِ.'),
    (4, 'تَمْيِيزُ النِّسْبَةِ (разъяснение отношения в предложении)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-object" dir="rtl" lang="ar">تَمْيِيزُ النِّسْبَةِ يُوَضِّحُ جُمْلَةً مُبْهَمَةَ النِّسْبَةِ قَبْلَهُ، وَأَصْلُهُ إِمَّا فَاعِلٌ، وَإِمَّا مُبْتَدَأٌ، وَإِمَّا مَفْعُولٌ بِهِ. وَحُكْمُهُ النَّصْبُ، وَيَكْثُرُ فِي التَّفْضِيلِ، وَالتَّعَجُّبِ، وَالْمَدْحِ وَالذَّمِّ، وَبَابِ فَعُلَ، وَبَابِ اِفْتَعَلَ.</span><p class="rule-study-text">تَمْيِيزُ النِّسْبَةِ разъясняет, в каком отношении верно предыдущее предложение. По исходной конструкции он восходит к субъекту, подлежащему или прямому дополнению; всегда стоит в винительном падеже и особенно часто встречается в пяти перечисленных контекстах.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Основной пример</span><div class="rule-example-list"><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar ar-tone-predicate" dir="rtl" lang="ar">حَسُنَ الطَّالِبُ خُلُقًا؛ أَيْ: حَسُنَ مِنْ جِهَةِ خُلُقِهِ.</span><span class="rule-example-ru">Студент хорош нравом; то есть хорош со стороны своего нрава.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Три исходные конструкции</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَصْلُ التَّمْيِيزِ</span><span class="rule-table-ru">исходная функция</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ بَعْدَ التَّحْوِيلِ</span><span class="rule-table-ru">выражение с تَمْيِيزٌ</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْأَصْلُ</span><span class="rule-table-ru">исходная конструкция и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-table-ru">субъект</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">حَسُنَ الطَّالِبُ خُلُقًا؛ اِزْدَادَ عَلِيٌّ عِلْمًا.</span><span class="rule-table-ru">Студент хорош нравом; Али возрос знанием.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">حَسُنَ خُلُقُ الطَّالِبِ؛ اِزْدَادَ عِلْمُ عَلِيٍّ.</span><span class="rule-table-ru">Хорош нрав студента; возросло знание Али.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُبْتَدَأٌ</span><span class="rule-table-ru">подлежащее именного предложения</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">أَنَا أَكْثَرُ مِنْكَ مَالًا.</span><span class="rule-table-ru">У меня больше имущества, чем у тебя.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مَالِي أَكْثَرُ.</span><span class="rule-table-ru">Моё имущество больше.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-table-ru">прямое дополнение</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">غَرَسْتُ الْحَدِيقَةَ أَزْهَارًا.</span><span class="rule-table-ru">Я засадил сад цветами.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">غَرَسْتُ أَزْهَارَ الْحَدِيقَةِ.</span><span class="rule-table-ru">Я посадил цветы сада.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример исходного дополнения</span><div class="rule-example-list"><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿وَفَجَّرۡنَا ٱلۡأَرۡضَ عُيُونٗا﴾</span><span class="rule-example-ru">И Мы заставили землю извергнуть источники; исходно: «извергли источники земли».</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Пять частых контекстов</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَوْضِعُ</span><span class="rule-table-ru">контекст</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">التَّفْضِيلُ</span><span class="rule-table-ru">сравнительная степень</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">أَنْتَ أَجْمَلُ مِنِّي صَوْتًا.</span><span class="rule-table-ru">Твой голос красивее моего.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">صَوْتًا</span><span class="rule-table-ru">разъясняет, в чём именно превосходство</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">التَّعَجُّبُ</span><span class="rule-table-ru">удивление</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَا أَحْسَنَ عَلِيًّا خَطًّا!</span><span class="rule-table-ru">Как прекрасен почерк Али!</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">خَطًّا</span><span class="rule-table-ru">разъясняет предмет удивления</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَدْحُ وَالذَّمُّ</span><span class="rule-table-ru">похвала и порицание</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">نِعْمَ خُلُقًا الصِّدْقُ؛ بِئْسَ خُلُقًا الْكَذِبُ.</span><span class="rule-table-ru">Прекрасный нрав — правдивость; дурной нрав — ложь.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">خُلُقًا</span><span class="rule-table-ru">разъясняет область похвалы или порицания</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بَابُ فَعُلَ</span><span class="rule-table-ru">модель فَعُلَ</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">حَسُنَ، كَبُرَ، عَظُمَ</span><span class="rule-table-ru">был хорош; был велик; был огромен</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">صِفَاتٌ لَازِمَةٌ</span><span class="rule-table-ru">глаголы устойчивого качества</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">بَابُ اِفْتَعَلَ</span><span class="rule-table-ru">модель اِفْتَعَلَ</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِمْتَلَأَ، اِرْتَفَعَ، اِزْدَادَ، اِشْتَعَلَ</span><span class="rule-table-ru">наполнился; поднялся; увеличился; воспламенился</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">أَفْعَالٌ يَكْثُرُ بَعْدَهَا التَّمْيِيزُ</span><span class="rule-table-ru">глаголы, после которых часто употребляется تَمْيِيزٌ</span></td></tr></tbody></table></div></div></div>', 'تَمْيِيزُ النِّسْبَةِ разъясняет, в каком отношении верно предыдущее предложение. По исходной конструкции он восходит к субъекту, подлежащему или прямому дополнению; всегда стоит в винительном падеже и особенно часто встречается в пяти перечисленных контекстах.', 'تَمْيِيزُ النِّسْبَةِ يُوَضِّحُ جُمْلَةً مُبْهَمَةَ النِّسْبَةِ قَبْلَهُ، وَأَصْلُهُ إِمَّا فَاعِلٌ، وَإِمَّا مُبْتَدَأٌ، وَإِمَّا مَفْعُولٌ بِهِ. وَحُكْمُهُ النَّصْبُ، وَيَكْثُرُ فِي التَّفْضِيلِ، وَالتَّعَجُّبِ، وَالْمَدْحِ وَالذَّمِّ، وَبَابِ فَعُلَ، وَبَابِ اِفْتَعَلَ.'),
    (5, 'صِيغَتَا التَّعَجُّبِ (две нормативные формы удивления)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">لِلتَّعَجُّبِ صِيغَتَانِ قِيَاسِيَّتَانِ: مَا أَفْعَلَهُ! وَأَفْعِلْ بِهِ! فَالْأُولَى جُمْلَةٌ اسْمِيَّةٌ خَبَرُهَا جُمْلَةٌ فِعْلِيَّةٌ، وَالثَّانِيَةُ فِعْلُ أَمْرٍ مَعَ بَاءٍ زَائِدَةٍ، وَالِاسْمُ بَعْدَهَا مَفْعُولٌ بِهِ مَنْصُوبٌ مَحَلًّا.</span><p class="rule-study-text">Удивление выражается двумя регулярными моделями: مَا أَفْعَلَهُ и أَفْعِلْ بِهِ. Шарх подробно разбирает синтаксис обеих форм и показывает, почему имя после добавочного بِـ считается прямым дополнением в винительной позиции.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Две формы</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الصِّيغَةُ</span><span class="rule-table-ru">модель</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مَا أَفْعَلَهُ!</span><span class="rule-table-ru">первая модель</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مَا أَحْسَنَ الِاسْتِقَامَةَ!</span><span class="rule-table-ru">Как прекрасна прямота!</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّعَجُّبُ بِمَا وَالْفِعْلِ الْمَاضِي</span><span class="rule-table-ru">удивление через مَا и форму прошедшего глагола</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَفْعِلْ بِهِ!</span><span class="rule-table-ru">вторая модель</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَحْسِنْ بِالِاسْتِقَامَةِ!</span><span class="rule-table-ru">Как прекрасна прямота!</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّعَجُّبُ بِفِعْلِ الْأَمْرِ وَالْبَاءِ الزَّائِدَةِ</span><span class="rule-table-ru">удивление через повелительную форму и добавочный بِـ</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранические примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿فَمَآ أَصۡبَرَهُمۡ عَلَى ٱلنَّارِ﴾</span><span class="rule-example-ru">Как же терпеливы они к Огню! — модель مَا أَفْعَلَهُ.</span></div><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿أَبۡصِرۡ بِهِۦ وَأَسۡمِعۡ﴾</span><span class="rule-example-ru">Как прекрасно Он видит и слышит! — модель أَفْعِلْ بِهِ.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">إِعْرَابُ مَا أَجْمَلَ الْوَرْدَةَ!</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar ar-tone-subject" dir="rtl" lang="ar">مَا: نَكِرَةٌ تَامَّةٌ مَبْنِيَّةٌ عَلَى السُّكُونِ فِي مَحَلِّ رَفْعٍ مُبْتَدَأٌ، وَهِيَ بِمَعْنَى شَيْءٍ.</span><span class="rule-example-ru">مَا — полное неопределённое слово, неизменяемое с сукуном, в позиции подлежащего; означает «нечто».</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">أَجْمَلَ: فِعْلٌ مَاضٍ مَبْنِيٌّ عَلَى الْفَتْحِ، وَالْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ وُجُوبًا تَقْدِيرُهُ هُوَ، يَعُودُ إِلَى مَا.</span><span class="rule-example-ru">أَجْمَلَ — прошедший глагол с фатхой; его обязательно скрытый субъект هُوَ возвращается к مَا.</span></div><div class="rule-example-card rule-term-object"><span class="rule-example-ar ar-tone-object" dir="rtl" lang="ar">الْوَرْدَةَ: مَفْعُولٌ بِهِ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">الْوَرْدَةَ — прямое дополнение в винительном падеже; показатель — явно выраженная фатха.</span></div><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar ar-tone-predicate" dir="rtl" lang="ar">الْجُمْلَةُ الْفِعْلِيَّةُ فِي مَحَلِّ رَفْعٍ خَبَرُ الْمُبْتَدَإِ.</span><span class="rule-example-ru">Глагольное предложение занимает позицию сказуемого подлежащего.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">إِعْرَابُ أَجْمِلْ بِالْوَرْدَةِ!</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">أَجْمِلْ: فِعْلُ أَمْرٍ مَبْنِيٌّ عَلَى السُّكُونِ، وَالْفَاعِلُ ضَمِيرٌ مُسْتَتِرٌ وُجُوبًا تَقْدِيرُهُ أَنْتَ.</span><span class="rule-example-ru">أَجْمِلْ — повелительный глагол, неизменяемый с сукуном; его обязательно скрытый субъект — أَنْتَ.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">بِـ: حَرْفُ جَرٍّ زَائِدٌ مَبْنِيٌّ عَلَى الْكَسْرِ، لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-example-ru">بِـ — добавочный предлог, неизменяемый с касрой, без синтаксической позиции.</span></div><div class="rule-example-card rule-term-object"><span class="rule-example-ar ar-tone-object" dir="rtl" lang="ar">الْوَرْدَةِ: مَفْعُولٌ بِهِ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الْمُقَدَّرَةُ، مَنَعَ مِنْ ظُهُورِهَا اشْتِغَالُ الْمَحَلِّ بِالْكَسْرَةِ.</span><span class="rule-example-ru">الْوَرْدَةِ — прямое дополнение в винительной позиции; показатель — подразумеваемая фатха, не проявившаяся из-за касры после добавочного предлога.</span></div></div></div></div>', 'Удивление выражается двумя регулярными моделями: مَا أَفْعَلَهُ и أَفْعِلْ بِهِ. Шарх подробно разбирает синтаксис обеих форм и показывает, почему имя после добавочного بِـ считается прямым дополнением в винительной позиции.', 'لِلتَّعَجُّبِ صِيغَتَانِ قِيَاسِيَّتَانِ: مَا أَفْعَلَهُ! وَأَفْعِلْ بِهِ! فَالْأُولَى جُمْلَةٌ اسْمِيَّةٌ خَبَرُهَا جُمْلَةٌ فِعْلِيَّةٌ، وَالثَّانِيَةُ فِعْلُ أَمْرٍ مَعَ بَاءٍ زَائِدَةٍ، وَالِاسْمُ بَعْدَهَا مَفْعُولٌ بِهِ مَنْصُوبٌ مَحَلًّا.')
)
update public.rules as r
set title = incoming.title,
    content = incoming.content,
    rule_kind = 'rule',
    summary = incoming.summary,
    rule_ar = incoming.rule_ar
from incoming
where r.course_name = 'Мединский курс (Том 4)'
  and r.lesson_number = '13'
  and r.sort_order = incoming.sort_order;

delete from public.rule_sources
where rule_id in (
  select id from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '13'
);

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'الدَّرْسُ الثَّالِثَ عَشَرَ
التَّمْيِيزُ
التَّمْيِيزُ : اسمٌ نكرةٌ يتضمَّنُ معنى ( مِنْ ) البَيَانِيَّة ، ويُذكر لِبيَان ما قبله من إِبْهَامٍ ، أو إِجْمَالٍ .
أنواعه :
أ- تمييز الذَّاتِ .        ب- تمييز النِّسْبَةِ .', 53, 53, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '13' and sort_order = 1;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'أ- تمييزُ الذَّاتِ
يُوَضِّحُ كلمةً مُبْهَمَةً قبلَه . ويقع بعد الْمَقَادِيرِ ، والمقادير أربعة أنواع ، هي :
1- الْمَقَايِيسُ ( الْمَمْسُوحَاتُ ، أي : الْمَسَاحَةُ ) نحو : عندي مِتْرٌ قُمَاشاً .
ونحو : بِعْتُ ذِرَاعاً وَرَقاً .
2- الْمَوْزُونَاتُ , نحو : تَصَدَّقْتُ بِغِرَامٍ ذَهَباً . اشتريتُ رِطْلاً عَسَلاً .
3- الْمَكِيلَاتُ , نحو : دفعتُ صَاعاً تَمْراً . لَهُ قَفِيزٌ بُرًّا . ( القَفِيزُ : مِكْيَالٌ قَدِيمٌ ) .
4- الْعَدَدُ , نحو : قرأتُ أحدَ عشرَ كتاباً ، أو بعد كناية العدد ، نحو : كَمْ كتاباً عندكَ ؟
الكلمات التي تحتها خط تمييز ذات ؛ لأنها وقعت بعد المقادير المذكورة .
أحكامه :
أ- يجوزُ نصبُه , نحو : عندي مترٌ قماشاً : تمييز منصوب وعلامة نصبه الفتحة الظاهرة .
ب- يجوزُ جرُّه بـ (مِنْ الْبَيَانِيَّةِ ) نحو : عندي مترٌ مِن قُماشٍ : تمييز مجرور بمن وعلامة جرِّه الكسرة الظاهرة .
ج- يجوزُ جرُّه بالإضافةِ , نحو : عندي مترُ قماشٍ : تمييز مجرور بالإضافة وعلامة جرِّه الكسرة الظاهرة .', 53, 54, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '13' and sort_order = 2;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'مَا يُلْحَقُ بتمييزِ الذَّاتِ :
يُلحق بتمييز الذَّات الدَّالُّ على ما يُشْبِهُ المِقْدَارَ .
نحو : عندي كيسٌ أرزاً . اشتريت جَرَّةً عسلاً . ما في السماء قَدْرُ رَاحَةٍ سَحَاباً .
أريدُ مِلْءَ ملعقةٍ عسلاً .
الكلمات التي تحتها خط ليست مقادير حقيقية ؛ لأنَّها لا تدلُّ على مِقْدَارٍ مُعَيَّنٍ مَحْدُود، ولكنها تُشبه المقادير التي ذكرناها سابقاً في مُطْلَق الْمِقْدار . فالكِيسُ مثلا يُشْبِهُ المكيال ، وقدْر راحة تدلّ على المقياس ؛ ولذلك عُدَّتْ من تمييز الذات .
ويجوز فيما يُشبه المقدار الأوجه الإعرابية الثلاثة السابقة ؛ فتقول : عندي كيسٌ أَرُزاً ، وعندي كيسٌ مِنْ أَرُزٍ ، وعندي كيسُ أَرُزٍ .
* أما إذا أضيف ما يشبه المقدار إلى غير التمييز جاز في التمييز وجهان :
النَّصب ، والجر بمن البيانية ( ولا يجوز الجر بالإضافة ) نحو : ما في السماءِ قدرُ راحةٍ سحاباً ، ويجوز : ما في السماء قدرُ راحةٍ مِنْ سحابٍ .
وتقول : أريدُ ملءَ ملعقةٍ عَسَلاً ، ويجوز : أريد ملءَ ملعقةٍ من عَسَلٍ . ومنه قوله تعالى :
﴿ فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ ﴾', 54, 54, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '13' and sort_order = 3;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'ب- تمييزُ النَّسْبَةِ
يُوَضِّح جُمْلَةً مُبْهَمَةَ النَّسْبَةِ قبلَه , نحو : حَسُنَ الطالبُ خُلُقاً , أي: حَسُنَ مِن جِهَةِ خُلُقِه .
أصله :
إما فاعل ، وإما مبتدأ ، وإما مفعول به .   أصله
1- ما أصله فاعل , نحو : حَسُنَ الطالبُ خُلُقاً ، أي : حَسُنَ خُلُقُ الطَّالبِ .
ونحو : اِزْدَادَ عليٌّ عِلْماً ، أي : ازداد عِلْمُ عليٍّ .
2- ما أصله مبتدأ ، نحو : أنا أكثرُ منك مالاً ، أي : مالِي أكثر .
3- ما أصله مفعول به , نحو : غَرَسْتُ الحديقةَ أَزْهَاراً ، أي : غرستُ أزهارَ الحديقةِ .
ومنه قوله تعالى : ﴿ وَفَجَّرْنَا الْأَرْضَ عُيُونًا ﴾ أي : وفجرنا عيونَ الأرضِ .
حكمه : النَّصْبُ .
مواضعه :
يكثر تمييز النَّسبة في المواضع الآتية :
1- التَّفْضِيلِ , نحو : أنت أجملُ مني صوتاً .
2- التَّعَجُّبُ , نحو : ما أحسنَ علياًّ خطاًّ .
3- الْمَدْحُ والذَّمُ , نحو : نِعْمَ خُلُقاً الصِّدْقُ . بِئْسَ خُلُقاً الكَذِبُ .
4- باب فَعُلَ , نحو : حَسُنَ , وكَبُرَ , وعَظُمَ .
5- باب اِفْتَعَلَ , نحو : امْتَلأَ , وارْتَفَعَ , وازْدَادَ , واشْتَعَلَ .', 55, 55, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '13' and sort_order = 4;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'صِيْغَتَا التَّعَجُّبِ
للتَّعَجُّبِ صِيغَتَانِ قِيَاسِيَّتَانِ :
1- ما أَفْعَلَهُ ! نحو: مَا أَحْسَنَ الاستقامةَ! ونحو قوله تعالى: ﴿ فَمَا أَصْبَرَهُمْ عَلَى النَّارِ ﴾ .
2- أَفْعِلْ بِهِ ! نحو : أَحْسِنْ بالاستقامةِ ! ونحو قوله تعالى : ﴿ أَبْصِرْ بِهِ وَأَسْمِعْ ﴾ .
الإعراب :
1- ما أجملَ الوردةَ !
ما : نكرة تامَّة مبنية على السكون في محل رفع مبتدأ . ( ما : بمعنى شيء ) .
أجْمَلَ : فعل ماض مبني على الفتح , والفاعل ضمير مستتر وجوبا تقديره ( هو ) يعود إلى ( ما ) .
الوردةَ : مفعول به منصوب وعلامة نصبه الفتحة الظاهرة . والجملة الفعلية في محل رفع خبر المبتدأ .
2- أَجْمِلْ بِالوردةِ !
أَجْمِلْ : فعل أمر مبني على السكون ، والفاعل ضمير مستتر وجوبا تقديره ( أنت ) .
بِـ : حرف جر زائد مبني على الكسر لا محلّ له من الإعراب .
الوردةِ : مفعول به منصوب وعلامة نصبه الفتحة المقدرة منع من ظهورها اشتغال المحل بالكسرة .', 55, 56, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '13' and sort_order = 5;

do $migration$
declare
  updated_count integer;
  source_count integer;
begin
  select count(*) into updated_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '13' and rule_ar is not null and btrim(rule_ar) <> '';
  select count(*) into source_count
  from public.rule_sources rs
  join public.rules r on r.id = rs.rule_id
  where r.course_name = 'Мединский курс (Том 4)' and r.lesson_number = '13';
  if updated_count <> 5 or source_count <> 5 then
    raise exception 'Book 4 lesson 13 QA failed: rules %, sources %', updated_count, source_count;
  end if;
end $migration$;

commit;
